from wcommon import legend, notes, head, sched
LAYER = "E-AV"
import math
ROWS=[(lambda s,x,y: (s.circle(x,y,0.22,color=1,lw=35), s.circle(x,y,0.17,color=250,lw=13)), "النجفة الحلقية (D-01): حلقتان Ø2.90 / Ø2.45 م، أحمر RAL 3003 خارجي وأسود داخلي، شاشة LED مرنة على الحلقة الداخلية", "ring chandelier with LED band"),
      (lambda s,x,y: s.rect(x-0.3,y-0.08,x+0.3,y+0.08,color=4), "شاشة LED داخلية P2.5 - 3.00×1.70 م", "indoor LED screen P2.5"),
      (lambda s,x,y: s.rect(x-0.15,y-0.1,x+0.15,y+0.1,color=6), "بروجكتر 5000 لومن ليزر مثبت سقف/جدار", "laser projector 5000 lm"),
      (lambda s,x,y: s.rect(x-0.3,y-0.1,x+0.3,y+0.1,color=6,lw=5), "منطقة عرض على الجدار (دهان شاشة عرض أبيض مطفي)", "projection area on wall")]
def _ring(s,cx,cy):
    s.circle(cx,cy,1.45,color=1,lw=50); s.circle(cx,cy,1.225,color=250,lw=35); s.circle(cx,cy,1.0,color=4,lw=13)
    for a in (45,135,225,315): s.dot(cx+1.35*math.cos(math.radians(a)),cy+1.35*math.sin(math.radians(a)),0.06)
    s.line((cx-0.3,cy),(cx+0.3,cy),lw=5); s.line((cx,cy-0.3),(cx,cy+0.3),lw=5)
    s.label(cx,cy,"النجفة الحلقية D-01\nØ2.90 / Ø2.45 م\nأسفل الحلقة +5.20 م",h=0.1)
    s.dim((cx-1.45,cy),(cx+1.45,cy),offset=1.7); s.dim((cx-1.225,cy),(cx+1.225,cy),offset=1.45)
def _common(s,floor):
    legend(s,floor,"رموز النجفة والشاشات - AV LEGEND",ROWS)
    sched(s,floor,"جدول النجفة والشاشات",["البند","المواصفة","العدد"],[("النجفة D-01","حلقتان حديد Ø2.90 و Ø2.45 م ارتفاع الحزام 0.45 م، تعليق 4 كابلات ستانلس Ø4 من بلاطة السطح بونش صيانة، الوزن ~120 كجم","1"),
        ("شاشة الحلقة","LED مرنة P4 محيطية على الحلقة الداخلية 7.7×0.3 م مع معالج فيديو","1"),("شاشة LED","داخلية P2.5 3.00×1.70 م على جدار الواجهة الداخلي باتجاه البار، أسفلها +4.20 م","1"),
        ("بروجكتر","ليزر 5000 لومن 1080p على الجدار الأيسر فوق الدرج، مسافة عرض 4.6 م","1"),("منطقة العرض","3.60×2.00 م على الجدار الأيمن للفراغ بعد النجفة، أسفلها +3.80 م","1"),("TV","شاشة 52 بوصة بمكتب المدير + شاشة الاجتماعات 65 بوصة","2"),("تغذية","نقاط S حسب مخطط الكهرباء + كابل HDMI/شبكة إلى راك السيرفر","-")])
    notes(s,floor,["النجفة تعلق في منتصف الفراغ المزدوج بين الدور الأرضي والميزانين من جسر حديد أعلى بلاطة السطح، بونش كهربائي لإنزالها للصيانة.",
        "شاشة LED الداخلية على الجدار الأمامي الداخلي (فوق زجاج المدخل) تشاهد من البار والجلسات، والبروجكتر يعرض على الجدار الأيمن بعد النجفة.","الأبعاد الحمراء: قطر الحلقات، مركز النجفة عن الجدران، مقاسات الشاشات ومسافة العرض."],"ملاحظات")
def draw_G(s):
    cx,cy=12.4,38.3; _ring(s,cx,cy)
    s.dim((9.3,cy),(cx,cy),offset=-1.0); s.dim((cx,cy),(14.4,cy),offset=-1.0); s.dim((cx,35.1),(cx,cy),offset=1.2,horizontal=False)
    s.rect(10.6,35.12,13.6,35.28,color=4,lw=35); s.text(10.6,35.45,"شاشة LED داخلية 3.00×1.70 م (تشاهد من البار)",h=0.1,color=4); s.dim((10.6,35.12),(13.6,35.12),offset=0.9)
    s.rect(9.35,38.15,9.65,38.45,color=6,lw=35); s.text(8.5,38.7,"بروجكتر ليزر 5000 لومن\nعلى الجدار الأيسر +4.5 م",h=0.09,attach=3)
    s.line((9.65,38.3),(14.3,38.3),color=6,lw=5,linetype="DASHED"); s.rect(14.25,36.5,14.4,40.1,color=6,lw=35); s.text(14.5,40.1,"منطقة عرض 3.6×2.0 م\nعلى الجدار الأيمن +3.80 م",h=0.09)
    s.dim((9.65,37.0),(14.25,37.0),offset=-0.4); s.dim((14.4,36.5),(14.4,40.1),offset=1.9,horizontal=False)
    _common(s,"G"); head(s,"G","مخطط النجفة والشاشات - الدور الأرضي: النجفة الحلقية في مركز الفراغ المزدوج، شاشة LED على الجدار الأمامي الداخلي، بروجكتر يعرض على الجدار الأيمن.")
def draw_M(s):
    cx,cy=3.2,13.1; _ring(s,cx,cy)
    s.dim((1.4,cy),(cx,cy),offset=-1.0); s.dim((cx,cy),(5.0,cy),offset=-1.0); s.dim((cx,9.9),(cx,cy),offset=1.2,horizontal=False)
    s.rect(1.5,9.92,4.5,10.08,color=4,lw=35); s.text(1.5,10.25,"شاشة LED داخلية 3.00×1.70 م أعلى زجاج الواجهة (+4.20 م عن الأرضي = +1.0 م عن الميزانين)",h=0.09,color=4)
    s.rect(0.32,12.95,0.62,13.25,color=6,lw=35); s.text(-0.3,13.5,"بروجكتر على جدار الدرج",h=0.09,attach=3)
    s.line((0.62,13.1),(5.0,13.1),color=6,lw=5,linetype="DASHED"); s.rect(5.0,11.3,5.15,14.9,color=6,lw=35); s.text(5.3,14.9,"منطقة عرض 3.6×2.0 م على جدار الفراغ الأيمن",h=0.09)
    s.dim((0.62,12.0),(5.0,12.0),offset=-0.4); s.dim((5.15,11.3),(5.15,14.9),offset=0.5,horizontal=False)
    s.rect(18.4,20.0,18.6,20.9,color=4,lw=35); s.text(18.7,20.9,"TV 52 بوصة",h=0.09); s.rect(13.62,14.0,13.75,15.2,color=4,lw=35); s.text(13.85,15.2,"شاشة اجتماعات 65 بوصة",h=0.09)
    _common(s,"M"); head(s,"M","مخطط النجفة والشاشات - الميزانين: النجفة الحلقية بالفراغ أمام البار، شاشة LED على الواجهة الداخلية، بروجكتر وجدار العرض، شاشات المكاتب.")
